sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var sinsei = current.sinsei_number;
    var pr_name = previous.name;
    var meisaiGr = new GlideRecord('x_1882833_organi_0_meisai');
    meisaiGr.addQuery('sinsei_number', sinsei);
    meisaiGr.addQuery('name', pr_name);
    meisaiGr.query();
    while (meisaiGr.next()) {
        meisaiGr.deleteRecord();
    }

    var cu_name = current.name;
    var shozokuGr = new GlideRecord('x_1882833_organi_0_shozoku');
    shozokuGr.addQuery('user_id', cr_name);
    shozokuGr.orderBy('kenmu_number');
    shozokuGr.query();

    var int = 0;
    while (shozokuGr.next()) {
        meisaiGr.initialize();
        meisaiGr.sinsei_number = sinsei;
        if (int == 0) {
            meisaiGr.kenmu_number = "主務";
        } else {
            meisaiGr.kenmu_number = "兼務" + int;
        }

    }

})(current, previous);
